function latestCredit(cid,date=CREDIT_AS_OF){const a=creditByCustomer.get(Number(cid))||[];let out=null;for(const x of a)if(x.snapshotDate<=date)out=x;else break;return out}
function customerBehavior(cid){const a=billByCustomer.get(Number(cid))||[];if(!a.length)return{first:null,last:null,days:null,interval:null,status:null};const dates=[...new Set(a.filter(x=>x.date<=DATA_AS_OF).map(x=>x.date))].sort();if(!dates.length)return{first:null,last:null,days:null,interval:null,status:null};const first=dates[0],last=dates.at(-1),days=Math.max(0,Math.floor((iso(DATA_AS_OF)-iso(last))/86400000));const gaps=[];for(let i=1;i<dates.length;i++)gaps.push((iso(dates[i])-iso(dates[i-1]))/86400000);const interval=avg(gaps);const rule=DATA.parameters.customerStatus.find(x=>days>=x.minimumDays&&(x.maximumDays==null||days<=x.maximumDays));return{first,last,days,interval,status:rule?.status||null}}
const behavior=new Map(DATA.dimensions.customers.map(c=>[c.id,customerBehavior(c.id)]));
function customerGuide(cid){return dims.customers.get(Number(cid))?.currentGuideId}
function customerRp(cid){return dims.guides.get(customerGuide(cid))?.currentRpId}
function currentBand(cid,mon=state?.filters?.toMonth||monthKey(DATA_AS_OF)){return (bandByCustomer.get(Number(cid))||[]).find(x=>x.month===mon)?.band||'SEM FATURAMENTO'}
function bandOrder(b){return DATA.parameters.revenueBands.indexOf(b)}
function matchList(a,v){return !a?.length||a.map(String).includes(String(v))}
function extraBalanceAt(cid,date){const a=limitByCustomer.get(Number(cid))||[];if(!a.length)return 0;let bal=a[0].previousLimit!=null?a[0].previousLimit:(a[0].newLimit-a[0].movement);for(const m of a){if(m.date<=date)bal=m.newLimit;else break}return bal}
function currentExtra(cid){const cr=latestCredit(cid);return cr?.limitExtra??extraBalanceAt(cid,CREDIT_AS_OF)}
function creditView(cid){const s=latestCredit(cid);if(!s)return null;const limitExtra=currentExtra(cid),limitNormal=s.limitCurrent,limitTotal=limitNormal+limitExtra,riskTotal=s.riskTotal,consumed=limitTotal-s.availableWithRecent,saturation=limitTotal?s.valueOpen/limitTotal:null;return{...s,limitNormal,limitExtra,limitTotal,riskTotal,consumed,saturation,available:s.availableWithRecent,delinquent:s.delinquent}}
function revenueBetween(cid,start,end){return sum((billByCustomer.get(Number(cid))||[]).filter(x=>x.date>=start&&x.date<=end),x=>x.value)}
function revenueWindow(cid,n){const end=DATA_AS_OF,start=firstDay(addMonths(monthKey(DATA_AS_OF),-(n-1)));return revenueBetween(cid,start,end)}
function revenueWindowAll(cid){const r3=revenueWindow(cid,3),r6=revenueWindow(cid,6),r12=revenueWindow(cid,12);return{r3,r6,r12,avg3:r3/3,avg6:r6/6,avg12:r12/12}}

