function periodInfo(){const f=state.filters,start=firstDay(f.fromMonth),selectedEnd=lastDay(f.toMonth),end=f.toMonth===monthKey(DATA_AS_OF)&&DATA_AS_OF<selectedEnd?DATA_AS_OF:selectedEnd,months=monthsBetween(f.fromMonth,f.toMonth);let comparison=null;if(f.compareMode==='previous'){const pf=addMonths(f.fromMonth,-months.length),pt=addMonths(f.toMonth,-months.length),day=+end.slice(-2);comparison={mode:'previous',fromMonth:pf,toMonth:pt,start:firstDay(pf),end:end<selectedEnd?clampDay(pt,day):lastDay(pt),months:monthsBetween(pf,pt)}}else if(f.compareMode==='yoy'){const pf=addMonths(f.fromMonth,-12),pt=addMonths(f.toMonth,-12),day=+end.slice(-2);comparison={mode:'yoy',fromMonth:pf,toMonth:pt,start:firstDay(pf),end:end<selectedEnd?clampDay(pt,day):lastDay(pt),months:monthsBetween(pf,pt)}}return{start,end,months,comparison}}
function comparisonText(){const p=periodInfo(),a=`${fmtDate.format(iso(p.start))} a ${fmtDate.format(iso(p.end))}`;if(!p.comparison)return`Período atual: ${a} · sem comparação`;return`Período atual: ${a} · Comparação: ${fmtDate.format(iso(p.comparison.start))} a ${fmtDate.format(iso(p.comparison.end))}`}
function salesContextCustomerIds(){const p=periodInfo(),need=state.filters.storeIds.length||state.filters.segmentIds.length||state.filters.saleGuideIds.length;if(!need)return null;const ids=new Set();for(const b of DATA.facts.billings){if(b.date<p.start||b.date>p.end)continue;if(!matchList(state.filters.storeIds,b.storeId))continue;if(!matchList(state.filters.segmentIds,dims.stores.get(b.storeId)?.segmentId))continue;if(!matchList(state.filters.saleGuideIds,b.saleGuideId))continue;ids.add(b.customerId)}return ids}
function inRangeBucket(v,id,type){if(type==='sat'){if(id==='0-50')return v<=.5;if(id==='50-70')return v>.5&&v<=.7;if(id==='70-90')return v>.7&&v<=.9;return v>.9}if(type==='limit'){if(id==='0-25')return v<=25000;if(id==='25-50')return v>25000&&v<=50000;if(id==='50-100')return v>50000&&v<=100000;return v>100000}if(type==='risk'){if(id==='0-10')return v<=10000;if(id==='10-25')return v>10000&&v<=25000;if(id==='25-50')return v>25000&&v<=50000;return v>50000}if(type==='move'){v=Math.abs(v);if(id==='0-5')return v<=5000;if(id==='5-15')return v>5000&&v<=15000;if(id==='15-30')return v>15000&&v<=30000;return v>30000}return true}
function baseCustomerSet(skipCurve=false){const salesIds=salesContextCustomerIds(),p=periodInfo(),salesInPeriod=new Set(DATA.facts.billings.filter(b=>b.date>=p.start&&b.date<=p.end).map(b=>b.customerId));const out=new Set();for(const c of DATA.dimensions.customers){const cid=c.id,cr=creditView(cid),bh=behavior.get(cid),band=currentBand(cid);if(!matchList(state.filters.customerIds,cid)||!matchList(state.filters.currentGuideIds,c.currentGuideId)||!matchList(state.filters.rpIds,customerRp(cid))||!matchList(state.filters.categories,currentCategory.get(cid)?.categoryId)||!matchList(state.filters.statuses,bh?.status)||!matchList(state.filters.bands,band))continue;if(salesIds&&!salesIds.has(cid))continue;if(state.filters.portfolio.length){if(state.filters.portfolio.includes('with-sales')&&!salesInPeriod.has(cid))continue;if(state.filters.portfolio.includes('without-sales')&&salesInPeriod.has(cid))continue}if(state.filters.delinquency.length&&cr){if(state.filters.delinquency.includes('yes')&&!(cr.delinquent>0))continue;if(state.filters.delinquency.includes('no')&&cr.delinquent>0)continue}else if(state.filters.delinquency.length&&!cr)continue;if(state.filters.saturationRanges.length&&(!cr||!state.filters.saturationRanges.some(x=>inRangeBucket(cr.saturation??0,x,'sat'))))continue;if(state.filters.hasExtra.length&&cr){if(state.filters.hasExtra.includes('yes')&&!(cr.limitExtra>0))continue;if(state.filters.hasExtra.includes('no')&&cr.limitExtra>0)continue}else if(state.filters.hasExtra.length&&!cr)continue;if(state.filters.limitRanges.length&&(!cr||!state.filters.limitRanges.some(x=>inRangeBucket(cr.limitTotal,x,'limit'))))continue;if(state.filters.riskRanges.length&&(!cr||!state.filters.riskRanges.some(x=>inRangeBucket(cr.riskTotal,x,'risk'))))continue;out.add(cid)}if(skipCurve||!state.filters.curveABCs.length)return out;const rows=billingsForSet(out,false),agg=aggregateRevenue(rows,'customers');const allowed=new Set(agg.filter(x=>state.filters.curveABCs.includes(x.curve)).map(x=>Number(x.id)));return new Set([...out].filter(x=>allowed.has(x)))}
function customerSet(){return baseCustomerSet(false)}
function billingsForSet(set,compare=false){const p=periodInfo(),a=compare?p.comparison:p;if(!a)return[];return DATA.facts.billings.filter(b=>b.date>=a.start&&b.date<=a.end&&set.has(b.customerId)&&matchList(state.filters.saleGuideIds,b.saleGuideId)&&matchList(state.filters.storeIds,b.storeId)&&matchList(state.filters.segmentIds,dims.stores.get(b.storeId)?.segmentId))}
function filteredBillings(compare=false){return billingsForSet(baseCustomerSet(true),compare).filter(b=>customerSet().has(b.customerId))}
function filteredMovements(){const p=periodInfo(),set=customerSet();return DATA.facts.limitExtraMovements.filter(x=>x.date>=p.start&&x.date<=p.end&&set.has(x.customerId)&&matchList(state.filters.movementTypes,x.type)&&(!state.filters.movementRanges.length||state.filters.movementRanges.some(r=>inRangeBucket(x.movement,r,'move'))))}
function latestCredits(){const out=[];for(const cid of customerSet()){const cr=creditView(cid);if(cr)out.push({customerId:cid,...cr})}return out}
function filteredBands(){const set=customerSet();return DATA.facts.revenueBands.filter(x=>x.month>=state.filters.fromMonth&&x.month<=state.filters.toMonth&&set.has(x.customerId))}
function revenueMetrics(){const cur=filteredBillings(),prev=filteredBillings(true),rev=sum(cur,x=>x.value),pr=sum(prev,x=>x.value);return{cur,prev,rev,prevRev:pr,delta:rev-pr,var:variation(rev,pr),customers:distinct(cur,x=>x.customerId),billings:distinct(cur,x=>x.id),guides:distinct(cur,x=>x.saleGuideId),stores:distinct(cur,x=>x.storeId)}}
function creditMetrics(){const rows=latestCredits(),limitTotal=sum(rows,x=>x.limitTotal),available=sum(rows,x=>x.available),open=sum(rows,x=>x.valueOpen),risk=sum(rows,x=>x.riskTotal),delinq=sum(rows,x=>x.delinquent),satValues=rows.map(x=>x.saturation).filter(x=>x!=null);return{rows,limitTotal,available,open,risk,delinq,saturationMedian:median(satValues),highSat:rows.filter(x=>(x.saturation??0)>.9).length,delinqCount:rows.filter(x=>x.delinquent>0).length}}
function extraMetrics(){const p=periodInfo(),set=customerSet(),moves=filteredMovements(),ids=[...set],initial=sum(ids,c=>extraBalanceAt(c,prevDay(p.start))),final=sum(ids,c=>currentExtra(c)),increases=sum(moves.filter(x=>x.movement>0),x=>x.movement),reductions=sum(moves.filter(x=>x.movement<0),x=>Math.abs(x.movement));return{initial,final,increases,reductions,net:increases-reductions,volume:increases+reductions,count:moves.length,increaseCount:moves.filter(x=>x.movement>0).length,reductionCount:moves.filter(x=>x.movement<0).length,customers:distinct(moves,x=>x.customerId),moves}}
function dimensionId(dim,r){if(dim==='customers')return r.customerId;if(dim==='guides')return r.saleGuideId;if(dim==='stores')return r.storeId;return dims.stores.get(r.storeId)?.segmentId}
function dimensionName(dim,id){if(dim==='customers')return dims.customers.get(Number(id))?.tradeName||'Cliente';if(dim==='guides')return dims.guides.get(Number(id))?.tradeName||'Guia';if(dim==='stores')return dims.stores.get(Number(id))?.tradeName||'Loja';return dims.segments.get(Number(id))?.name||'Segmento'}
function aggregateRevenue(rows,dim){const m=new Map(),total=sum(rows,x=>x.value)||1;for(const r of rows){const id=dimensionId(dim,r);if(id==null)continue;let x=m.get(id);if(!x)m.set(id,x={id,name:dimensionName(dim,id),revenue:0,customers:new Set(),guides:new Set(),stores:new Set(),billings:new Set()});x.revenue+=r.value;x.customers.add(r.customerId);x.guides.add(r.saleGuideId);x.stores.add(r.storeId);x.billings.add(r.id)}let cum=0,rank=0;return[...m.values()].sort((a,b)=>b.revenue-a.revenue).map(x=>{rank++;const share=x.revenue/total;cum+=share;return{...x,rank,share,cumulative:cum,curve:cum<=.5?'A':cum<=.8?'B':'C',customerCount:x.customers.size,guideCount:x.guides.size,storeCount:x.stores.size,billingCount:x.billings.size}})}
function revenueByMonth(rows,months){const m=new Map(months.map(x=>[x,0]));for(const r of rows){const mon=monthKey(r.date);if(m.has(mon))m.set(mon,m.get(mon)+r.value)}return[...m].map(([month,value])=>({month,value}))}
function revenueEntityRows(dim){const cur=aggregateRevenue(filteredBillings(),dim),prevMap=new Map(aggregateRevenue(filteredBillings(true),dim).map(x=>[String(x.id),x.revenue]));return cur.map(x=>({...x,previousRevenue:prevMap.get(String(x.id))||0,deltaRevenue:x.revenue-(prevMap.get(String(x.id))||0),deltaPercent:variation(x.revenue,prevMap.get(String(x.id))||0)}))}

function iconChar(m){return({executive:'◆',revenue:'▥',credit:'◈',extra:'↕',bands:'▤',customer:'◎'})[m]||'•'}
function railHtml(){const items=[['executive','Visão Executiva','Resumo integrado'],['revenue','Faturamento','Vendas e concentração'],['credit','Crédito','Limite, exposição e compras'],['extra','Limite Extra','Concessões e evolução'],['bands','Faixas','Trajetória de faturamento'],['customer','Cliente 360','Visão integrada do cliente']];return`<aside class="rail"><div class="rail-inner"><div class="brand"><img src="${LOGO}" alt="Master Shopping"><div class="brand-copy"><strong>Master Hub</strong><small>Shopping Atacadista</small></div></div><div class="rail-label">Módulos</div><nav class="nav">${items.map(([id,l,s])=>`<button class="nav-btn ${state.module===id?'active':''}" data-module="${id}" ${state.module===id?'aria-current="page"':''}><span class="nav-icon">${iconChar(id)}</span><span class="rail-text"><b>${l}</b><small>${s}</small></span></button>`).join('')}</nav><div class="spacer"></div></div></aside>`}
function topHtml(){const tabs=moduleTabs[state.module]||[];return`<header class="topbar"><div class="product"><span>Master Hub · v12</span><strong>${moduleLabels[state.module]}</strong></div><nav class="tabs" aria-label="Páginas de ${moduleLabels[state.module]}">${tabs.map(([id,l])=>`<button class="tab ${state.tabs[state.module]===id?'active':''}" data-tab="${id}" ${state.tabs[state.module]===id?'aria-current="page"':''}>${l}</button>`).join('')}</nav><div class="fresh"><strong>Vendas até ${fmtDate.format(iso(DATA_AS_OF))} · Crédito até ${fmtDate.format(iso(CREDIT_AS_OF))}</strong><span>Base fictícia · ${DATA.meta.totals.customers} clientes · situação cadastral em ${fmtDate.format(iso(ANALYSIS_DATE))}</span></div></header>`}
function pageHead(title,copy){return`<section class="page-head"><div><span class="eyebrow">${moduleLabels[state.module]}</span><h1>${title}</h1><p>${copy||''}</p></div><div class="page-context">${comparisonText()}</div></section>`}
function info(label,text){return`<span class="tooltip"><span>${label}</span><button class="info" aria-label="Informação sobre ${esc(label)}">i</button><span class="tip" role="tooltip">${esc(text)}</span></span>`}
const HELP={
 represent:'Representatividade — percentual do faturamento desta entidade sobre o faturamento total resultante dos filtros atuais.',
 cumulative:'Acumulado — soma progressiva da representatividade após ordenar a dimensão por faturamento decrescente.',
 abc:'Curva ABC — classificação pela representatividade acumulada: A até 50%, B acima de 50% até 80% e C acima de 80%.',
 saturation:'Saturação — Valor em aberto ÷ Limite total, conforme regra vigente do cenário de Crédito.',
 risk:'Risco total — Valor em aberto + Valor recente, conforme regra vigente da V11.',
 recent:'Recente — valor considerado na janela histórica de 60 dias da regra vigente de Crédito.',
 available:'Crédito disponível — valor disponível com o componente Recente, preservando a regra vigente da V11. Valores negativos permanecem negativos.',
 delinquency:'Inadimplência — valor inadimplente informado na posição de Crédito. É apresentado separadamente do Risco total.',
 delta:'Variação — diferença entre o período atual e o período comparativo selecionado. As datas aparecem no contexto da página.',
 bands:'Faixa inicial é a primeira referência mensal do período filtrado; Faixa final é a última referência mensal do período filtrado.',
 effect:'Compara os dois meses-calendário completos anteriores ao aumento de Limite Extra com os dois meses completos posteriores. Associação temporal não prova causalidade.'
};
function abcBadge(c){const x=String(c||'C');return`<span class="badge abc-${x.toLowerCase()}">${x==='A'?'★':x==='B'?'◆':'●'} ${x}</span>`}
function statusBadge(s){const x=s||'INATIVO',label=x==='ATIVO'?'Ativo':x==='ATENCAO'?'Atenção':'Inativo',sym=x==='ATIVO'?'✓':x==='ATENCAO'?'!':'×';return`<span class="badge status-${x.toLowerCase()}">${sym} ${label}</span>`}
function delinquencyBadge(v){return v>0?`<span class="badge risk-bad">! Com inadimplência</span>`:`<span class="badge risk-ok">✓ Sem inadimplência</span>`}
function saturationBadge(v){if(v==null)return'—';if(v>.9)return`<span class="badge risk-bad">! ${fmtPct.format(v)}</span>`;if(v>.7)return`<span class="badge risk-warn">! ${fmtPct.format(v)}</span>`;return`<span class="badge risk-ok">✓ ${fmtPct.format(v)}</span>`}
function migrationBadge(v){return v>0?`<span class="badge migration-up">↑ Subiu</span>`:v<0?`<span class="badge migration-down">↓ Caiu</span>`:`<span class="badge migration-same">→ Manteve</span>`}
function comparisonBadge(v){if(v==null)return`<span class="badge migration-same">Sem comparação</span>`;return`<span class="badge ${v>=0?'migration-up':'migration-down'}">${v>=0?'↑':'↓'} ${v>=0?'+':''}${fmtPct.format(v)}</span>`}
function metricCards(items){return`<section class="score">${items.slice(0,6).map(x=>`<article><span>${x.help?info(x.label,x.help):x.label}</span><strong class="${x.cls||''}">${x.value}</strong><small>${x.sub||''}</small></article>`).join('')}</section>`}
function panel(title,subtitle,body,controls=''){return`<article class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle||''}</p></div>${controls?`<div class="panel-controls">${controls}</div>`:''}</div>${body}</article>`}
function barList(data,clickAttr=''){const max=Math.max(1,...data.map(x=>Math.abs(x.value||0)));return`<div class="panel-body barlist">${data.map(x=>`<${clickAttr?'button':'div'} class="barrow" ${clickAttr?`${clickAttr}="${esc(x.id??x.label)}"`:''}><div><strong>${esc(x.label)}</strong><small>${x.meta||''}</small><div class="bar"><i style="width:${Math.min(100,Math.abs(x.value||0)/max*100)}%"></i></div></div><b>${x.display??fmtN.format(x.value||0)}</b></${clickAttr?'button':'div'}>`).join('')}</div>`}
function lineChart(series1,series2=null,labels=['Período atual','Comparação'],small=false){const p=periodInfo(),n=Math.max(series1.length,series2?.length||0),vals=[...series1,...(series2||[])].map(x=>x.value||0),max=Math.max(1,...vals),W=800,H=small?178:245,pad={l:48,r:14,t:12,b:small?25:42},X=i=>pad.l+(n<=1?0:i*(W-pad.l-pad.r)/(n-1)),Y=v=>H-pad.b-v/max*(H-pad.t-pad.b),path=s=>s.map((d,i)=>`${i?'L':'M'}${X(i).toFixed(1)},${Y(d.value||0).toFixed(1)}`).join(' ');const grids=[0,.25,.5,.75,1].map(t=>{const y=pad.t+t*(H-pad.t-pad.b),v=max*(1-t);return`<line class="gridline" x1="${pad.l}" x2="${W-pad.r}" y1="${y}" y2="${y}"/><text class="axis" x="${pad.l-6}" y="${y+3}" text-anchor="end">${v>=1e6?(v/1e6).toFixed(1)+'m':Math.round(v/1000)+'k'}</text>`}).join('');const labelsX=series1.map((d,i)=>{const comp=series2?.[i]?.month?`<tspan x="${X(i)}" dy="10">${monthName(series2[i].month)}</tspan>`:'';return`<text class="axis" x="${X(i)}" y="${H-(small?7:18)}" text-anchor="middle">${monthName(d.month)}${!small&&comp?comp:''}</text>`}).join('');const dots=s=>s.map((d,i)=>`<circle cx="${X(i)}" cy="${Y(d.value||0)}" r="3" fill="#fff" stroke="${s===series1?'#a91f24':'#939aa1'}"><title>${monthName(d.month)}: ${fmtBRL2.format(d.value||0)}</title></circle>`).join('');return`<div class="chart ${small?'small':''}"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolução temporal. ${comparisonText()}">${grids}${series2?`<path class="line-gray" d="${path(series2)}"/>${dots(series2)}`:''}<path class="line-red" d="${path(series1)}"/>${dots(series1)}${labelsX}</svg></div><div class="legend"><span><i></i>${labels[0]}</span>${series2?`<span><i class="gray"></i>${labels[1]}</span>`:''}</div>`}
function multiBandChart(metric='customers'){const months=periodInfo().months,bands=DATA.parameters.revenueBands,colors=['#8d9399','#48647d','#6c7d8b','#9b7a32','#8a4a4e','#a91f24'],W=850,H=250,pad={l:52,r:18,t:15,b:34};const datasets=bands.map((band,bi)=>({band,values:months.map(mon=>{const rows=DATA.facts.revenueBands.filter(x=>x.month===mon&&customerSet().has(x.customerId)&&x.band===band);return metric==='revenue'?sum(rows,x=>x.revenue):rows.length}),color:colors[bi]}));const max=Math.max(1,...datasets.flatMap(d=>d.values)),X=i=>pad.l+(months.length<=1?0:i*(W-pad.l-pad.r)/(months.length-1)),Y=v=>H-pad.b-v/max*(H-pad.t-pad.b),path=arr=>arr.map((v,i)=>`${i?'L':'M'}${X(i)},${Y(v)}`).join(' ');return`<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolução mensal das faixas">${[0,.25,.5,.75,1].map(t=>{const y=pad.t+t*(H-pad.t-pad.b);return`<line class="gridline" x1="${pad.l}" x2="${W-pad.r}" y1="${y}" y2="${y}"/>`}).join('')}${datasets.map(d=>`<path d="${path(d.values)}" fill="none" stroke="${d.color}" stroke-width="2"><title>${esc(d.band)}</title></path>`).join('')}${months.map((m,i)=>`<text class="axis" x="${X(i)}" y="${H-8}" text-anchor="middle">${monthName(m)}</text>`).join('')}</svg></div><div class="legend" style="flex-wrap:wrap">${datasets.map(d=>`<span><i style="border-color:${d.color}"></i>${esc(d.band)}</span>`).join('')}</div>`}

function monthOptions(sel,min,max){return monthsBetween(min,max).map(m=>`<option ${m===sel?'selected':''} value="${m}">${monthName(m)}</option>`).join('')}
function filterText(k){const a=state.filters[k],meta=filterMeta[k];if(!a.length)return'Todos';if(a.length===1)return meta.items().find(x=>String(x.id)===String(a[0]))?.label||a[0];return`${a.length} selecionados`}
function filterBtn(k){return`<div class="filter-slot"><span class="filter-label">${filterMeta[k].label}</span><button class="filter-btn ${state.filters[k].length?'active':''} ${state.openFilter===k?'open':''}" data-filter="${k}" aria-haspopup="listbox" aria-expanded="${state.openFilter===k}"><span>${esc(filterText(k))}</span><b>${state.filters[k].length||'Todos'}</b></button></div>`}
function activeAdvancedCount(spec){return spec.advanced.filter(k=>state.filters[k]?.length).length}
function filterHtml(){const spec=filterSpecs[state.module]||filterSpecs.executive,min=DATA.meta.months[0],max=DATA.meta.months.at(-1),active=Object.entries(state.filters).some(([k,v])=>Array.isArray(v)&&v.length)||state.filters.fromMonth!=='2026-01'||state.filters.toMonth!=='2026-06'||state.filters.compareMode!=='previous',advCount=activeAdvancedCount(spec);const chips=[];for(const k of [...spec.primary,...spec.advanced])if(state.filters[k]?.length)chips.push(`<button class="chip active" data-clear="${k}" title="Remover filtro">${filterMeta[k].label}: ${esc(filterText(k))} ×</button>`);const compareSelect=(state.module==='revenue'||state.module==='executive')?`<select class="select" data-compare aria-label="Modo de comparação"><option value="previous" ${state.filters.compareMode==='previous'?'selected':''}>Período anterior</option><option value="yoy" ${state.filters.compareMode==='yoy'?'selected':''}>Mesmo período ano anterior</option><option value="none" ${state.filters.compareMode==='none'?'selected':''}>Sem comparação</option></select>`:'';return`<section class="filter-shell"><div class="filters"><div class="filter-row ${spec.primary.length<=3?'compact':''}"><div><span class="filter-label">Período</span><div class="period"><select class="select" data-month="fromMonth">${monthOptions(state.filters.fromMonth,min,state.filters.toMonth)}</select><select class="select" data-month="toMonth">${monthOptions(state.filters.toMonth,state.filters.fromMonth,max)}</select></div></div>${spec.primary.map(filterBtn).join('')}<div class="filter-tools">${spec.advanced.length?`<button class="ghost ${advCount?'active':''}" data-action="advanced">${state.advancedOpen?'Menos filtros':'Mais filtros'}${advCount?` (${advCount})`:''}</button>`:''}<button class="ghost" data-action="clear" ${active?'':'disabled'}>Limpar filtros</button></div></div>${state.advancedOpen&&spec.advanced.length?`<div class="advanced"><div class="advanced-head"><span><b class="filter-scope">Filtros adicionais</b> · use apenas dimensões aplicáveis a esta análise</span>${compareSelect}</div>${spec.advanced.map(filterBtn).join('')}</div>`:''}<div class="chips"><span class="chip">${monthName(state.filters.fromMonth)} → ${monthName(state.filters.toMonth)}</span>${chips.join('')}<span class="scope-note">${fmtN.format(customerSet().size)} clientes no contexto</span></div><div class="compare-line"><strong>Comparação:</strong><span>${comparisonText()}</span>${!state.advancedOpen&&compareSelect?`<span style="margin-left:auto">${compareSelect}</span>`:''}</div></div></section>`}
function popoverHtml(k,anchor){const r=anchor.getBoundingClientRect(),left=Math.min(r.left,innerWidth-370),top=Math.min(r.bottom+5,innerHeight-390),q=normalize(state.filterSearch),selected=state.filters[k].map(String),items=filterMeta[k].items().filter(x=>!q||normalize(x.label).includes(q));return`<div class="popover" style="left:${Math.max(8,left)}px;top:${Math.max(8,top)}px" data-pop role="dialog" aria-label="Filtro ${esc(filterMeta[k].label)}"><div class="pop-head"><strong>${filterMeta[k].label}</strong><button data-clear="${k}">Limpar</button></div><div class="pop-search"><input autofocus data-filter-search placeholder="Buscar..." value="${esc(state.filterSearch)}" aria-label="Buscar ${esc(filterMeta[k].label)}"></div><div class="opts" role="listbox" aria-multiselectable="true">${items.map(x=>`<button class="opt ${selected.includes(String(x.id))?'sel':''}" role="option" aria-selected="${selected.includes(String(x.id))}" data-toggle="${k}" data-value="${esc(x.id)}"><span class="box">${selected.includes(String(x.id))?'✓':''}</span><span><strong>${esc(x.label)}</strong></span><span class="count"></span></button>`).join('')}</div></div>`}

function tableModeKey(id){return`${state.module}:${state.tabs[state.module]}:${id}`}
function getTableMode(id){return state.tableModes[tableModeKey(id)]||'summary'}
function setTableMode(id,mode){state.tableModes[tableModeKey(id)]=mode}
function cellHtml(r,c,entityKind){const[k,label,type]=c,v=r[k];if(k==='name'&&entityKind){const id=r.id??r.customerId??r.reviewId;return`<td><button class="entity-link" data-open-entity="${entityKind}" data-id="${id}">${esc(v)} →</button></td>`}if(type==='money')return`<td class="num">${v==null?'—':fmtBRL2.format(v)}</td>`;if(type==='moneySigned')return`<td class="num ${v>0?'up':v<0?'down':''}">${v==null?'—':`${v>=0?'+':''}${fmtBRL2.format(v)}`}</td>`;if(type==='pct')return`<td class="num ${v!=null&&v<0?'down':''}">${v==null?'—':fmtPct.format(v)}</td>`;if(type==='ratio')return`<td class="num">${v==null?'—':`${fmtD1.format(v)}×`}</td>`;if(type==='number')return`<td class="num">${v==null?'—':fmtN.format(v)}</td>`;if(type==='days')return`<td class="num">${v==null?'—':`${fmtN.format(v)} dias`}</td>`;if(type==='date')return`<td>${v?fmtDate.format(iso(v)):'—'}</td>`;if(type==='abc')return`<td>${abcBadge(v)}</td>`;if(type==='status')return`<td>${statusBadge(v)}</td>`;if(type==='delinq')return`<td>${delinquencyBadge(v||0)}</td>`;if(type==='saturation')return`<td>${saturationBadge(v)}</td>`;if(type==='migration')return`<td>${migrationBadge(v)}</td>`;return`<td>${v==null?'—':esc(v)}</td>`}
function cellText(r,c){const v=r[c[0]],t=c[2];if(v==null)return'—';if(t==='money'||t==='moneySigned')return fmtBRL.format(v);if(t==='pct'||t==='saturation')return fmtPct.format(v);if(t==='ratio')return `${fmtD1.format(v)}×`;if(t==='date')return fmtDate.format(iso(v));if(t==='days')return`${fmtN.format(v)} dias`;if(t==='abc')return`Curva ${v}`;if(t==='status')return v==='ATIVO'?'Ativo':v==='ATENCAO'?'Atenção':'Inativo';if(t==='migration')return v>0?'Subiu':v<0?'Caiu':'Manteve';return String(v)}
function tablePanel(id,title,subtitle,rows,summaryCols,detailCols=summaryCols,entityKind=null){const mode=getTableMode(id),cols=mode==='detail'?detailCols:summaryCols,q=normalize(state.tableSearch);let data=[...rows];if(q)data=data.filter(r=>cols.some(c=>normalize(cellText(r,c)).includes(q)));if(state.sort.key&&cols.some(c=>c[0]===state.sort.key))data.sort((a,b)=>{const av=a[state.sort.key],bv=b[state.sort.key],res=typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??''),'pt-BR',{numeric:true});return state.sort.dir==='asc'?res:-res});const toggle=detailCols.length>summaryCols.length?`<div class="view-toggle"><button class="${mode==='summary'?'active':''}" data-table-mode="summary" data-table-id="${id}">Resumida</button><button class="${mode==='detail'?'active':''}" data-table-mode="detail" data-table-id="${id}">Detalhada</button></div>`:'';const mobile=data.slice(0,40).map(r=>`<article class="mcard"><h4>${esc(r.name||r.customer||r.guide||r.date||'Registro')}</h4>${cols.slice(1,6).map(c=>`<p><b>${c[1]}:</b> ${esc(cellText(r,c))}</p>`).join('')}${entityKind&&r.id!=null?`<button class="ghost" data-open-entity="${entityKind}" data-id="${r.id}">Abrir análise</button>`:''}</article>`).join('');return`<article class="table-panel"><div class="table-head"><div><h3>${title}</h3><p>${subtitle||''}</p></div><span class="chip">${fmtN.format(data.length)} registros</span></div><div class="table-tools"><label class="search"><span>Buscar nesta tabela</span><input data-table-search value="${esc(state.tableSearch)}" placeholder="Buscar..."></label><div class="table-actions">${toggle}<button class="ghost" data-export="csv">CSV</button><button class="ghost" data-export="xlsx">Excel</button></div></div><div class="table-wrap"><table class="data"><thead><tr>${cols.map(c=>`<th class="${['money','moneySigned','pct','ratio','number','days','saturation'].includes(c[2])?'num':''}"><button class="sort" data-sort="${c[0]}">${c[1]}${state.sort.key===c[0]?(state.sort.dir==='asc'?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${cols.map(c=>cellHtml(r,c,entityKind)).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}"><div class="empty">Nenhum registro para este recorte.</div></td></tr>`}</tbody></table></div><div class="cards-mobile">${mobile}</div></article>`}

function revenueCustomerRows(){const agg=revenueEntityRows('customers'),rows=filteredBillings(),by=new Map();for(const b of rows){let x=by.get(b.customerId);if(!x)by.set(b.customerId,x={stores:new Set(),billings:new Set(),guides:new Set()});x.stores.add(b.storeId);x.billings.add(b.id);x.guides.add(b.saleGuideId)}return agg.map(x=>{const cid=Number(x.id),bh=behavior.get(cid)||{},cr=creditView(cid),b=by.get(cid)||{stores:new Set(),billings:new Set(),guides:new Set()};return{...x,id:cid,name:dims.customers.get(cid)?.tradeName,category:currentCategory.get(cid)?.categoryId,guide:dims.guides.get(customerGuide(cid))?.tradeName,status:bh.status,band:currentBand(cid),first:bh.first,last:bh.last,days:bh.days,interval:bh.interval,stores:b.stores.size,billings:b.billings.size,guides:b.guides.size,delinquent:cr?.delinquent??null,ticket:b.billings.size?x.revenue/b.billings.size:null,frequency:bh.interval==null?null:bh.interval}})}
function revenueGuideRows(){return revenueEntityRows('guides').map(x=>({...x,id:Number(x.id),name:dims.guides.get(Number(x.id))?.tradeName}))}
function revenueStoreRows(){return revenueEntityRows('stores').map(x=>({...x,id:Number(x.id),name:dims.stores.get(Number(x.id))?.tradeName,segment:dims.segments.get(dims.stores.get(Number(x.id))?.segmentId)?.name}))}
function revenueSegmentRows(){return revenueEntityRows('segments').map(x=>({...x,id:Number(x.id),name:dims.segments.get(Number(x.id))?.name}))}
function revenueRowsForDimension(dim){if(dim==='customers')return revenueCustomerRows();if(dim==='guides')return revenueGuideRows();if(dim==='stores')return revenueStoreRows();return revenueSegmentRows()}
function curveAShare(rows){return sum(rows.filter(x=>x.curve==='A'),x=>x.share)}
function revenueOverview(){const r=revenueMetrics(),p=periodInfo(),agg=revenueRowsForDimension(state.revenueConcentration),curSeries=revenueByMonth(r.cur,p.months),compSeries=p.comparison?revenueByMonth(r.prev,p.comparison.months):null;const cards=[{label:'Faturamento total',value:moneyShort(r.rev),sub:`${fmtN.format(r.billings)} faturamentos distintos`},{label:'Nº de faturamentos',value:fmtN.format(r.billings),sub:'distinct count do identificador transacional'},{label:'Valor médio por faturamento',value:moneyShort(r.billings?r.rev/r.billings:0),sub:'Faturamento ÷ faturamentos'},{label:'Clientes com faturamento',value:fmtN.format(r.customers),sub:'compradores no período'},{label:'Variação',value:r.var==null?'—':`${r.var>=0?'+':''}${fmtPct.format(r.var)}`,sub:r.var==null?'Sem comparação':`${r.delta>=0?'+':''}${moneyShort(r.delta)} · ${comparisonText()}`,cls:r.var==null?'':r.var>=0?'up':'down',help:HELP.delta},{label:'Curva A',value:fmtPct.format(curveAShare(agg)),sub:`representatividade em ${state.revenueConcentration}`,help:HELP.abc}];const dimButtons=[['customers','Clientes'],['guides','Guias'],['stores','Lojas'],['segments','Segmentos']].map(([id,l])=>`<button class="${state.revenueConcentration===id?'active':''}" data-concentration="${id}">${l}</button>`).join('');const bars=agg.slice(0,10).map(x=>({id:x.id,label:x.name,value:x.revenue,display:fmtPct.format(x.share),meta:`${moneyShort(x.revenue)} · acum. ${fmtPct.format(x.cumulative)}`}));const summaryCols=[['name',state.revenueConcentration==='customers'?'Cliente':state.revenueConcentration==='guides'?'Guia':state.revenueConcentration==='stores'?'Loja':'Segmento','text'],['revenue','Faturamento','money'],['share','Representatividade','pct'],['cumulative','Acumulado','pct'],['curve','Curva','abc']];return`${pageHead('Visão Geral','Leia o resultado, compare períodos e identifique rapidamente onde o faturamento está concentrado.')}${metricCards(cards)}<section class="grid2">${panel('Evolução do faturamento',comparisonText(),lineChart(curSeries,compSeries,['Período atual','Comparação']))}${panel('Concentração dinâmica','Alterne a dimensão sem sair da Visão Geral',barList(bars),`<div class="view-toggle">${dimButtons}</div>`)}</section>${tablePanel('revenue-overview','Concentração no recorte','Faturamento, Representatividade, Acumulado e Curva ABC.',agg,summaryCols,summaryCols,state.revenueConcentration==='customers'?'customer':state.revenueConcentration==='guides'?'guide':state.revenueConcentration==='stores'?'store':'segment')}`}
