function creditCustomerRows(){return[...customerSet()].map(cid=>{const c=dims.customers.get(cid),cr=creditView(cid);if(!cr)return null;const rw=revenueWindowAll(cid),avgMonthly=rw.avg12,bh=behavior.get(cid);return{id:cid,name:c.tradeName,guide:dims.guides.get(c.currentGuideId)?.tradeName,limitNormal:cr.limitNormal,limitExtra:cr.limitExtra,limitTotal:cr.limitTotal,open:cr.valueOpen,available:cr.available,saturation:cr.saturation,risk:cr.riskTotal,delinquent:cr.delinquent,recent:cr.valueRecent,r3:rw.r3,r6:rw.r6,r12:rw.r12,avgMonthly,limitToAvg:avgMonthly?cr.limitTotal/avgMonthly:null,openToAvg:avgMonthly?cr.valueOpen/avgMonthly:null,band:currentBand(cid),category:currentCategory.get(cid)?.categoryId,status:bh?.status,last:bh?.last,days:bh?.days}}).filter(Boolean)}
function creditGuideRows(){const rows=creditCustomerRows(),m=new Map();for(const r of rows){const gid=customerGuide(r.id);let x=m.get(gid);if(!x)m.set(gid,x={id:gid,name:dims.guides.get(gid)?.tradeName,customers:0,r3:0,r6:0,r12:0,limitTotal:0,available:0,open:0,risk:0,delinquent:0,delinqCustomers:0});x.customers++;x.r3+=r.r3;x.r6+=r.r6;x.r12+=r.r12;x.limitTotal+=r.limitTotal;x.available+=r.available;x.open+=r.open;x.risk+=r.risk;x.delinquent+=r.delinquent;if(r.delinquent>0)x.delinqCustomers++}return[...m.values()].map(x=>({...x,saturation:x.limitTotal?x.open/x.limitTotal:null})).sort((a,b)=>b.risk-a.risk)}
function saturationDistribution(rows){return[{id:'0-50',label:'Até 50%',rows:rows.filter(x=>(x.saturation??0)<=.5)},{id:'50-70',label:'50% a 70%',rows:rows.filter(x=>x.saturation>.5&&x.saturation<=.7)},{id:'70-90',label:'70% a 90%',rows:rows.filter(x=>x.saturation>.7&&x.saturation<=.9)},{id:'90+',label:'Acima de 90%',rows:rows.filter(x=>x.saturation>.9)}]}
function creditOverview(){const rows=creditCustomerRows(),m=creditMetrics(),dist=saturationDistribution(rows),riskData=state.creditRiskEntity==='customers'?[...rows].sort((a,b)=>b.risk-a.risk).slice(0,10):creditGuideRows().slice(0,10);const cards=[{label:'Limite total',value:moneyShort(m.limitTotal),sub:`Limite Extra: ${moneyShort(sum(rows,x=>x.limitExtra))}`},{label:'Limite disponível',value:moneyShort(m.available),sub:'com componente Recente',cls:m.available<0?'down':'',help:HELP.available},{label:'Valor em aberto',value:moneyShort(m.open),sub:'exposição atual'},{label:'Risco total',value:moneyShort(m.risk),sub:'Aberto + Recente',help:HELP.risk},{label:'Inadimplência total',value:moneyShort(m.delinq),sub:`${fmtN.format(m.delinqCount)} clientes`,cls:m.delinq>0?'down':'',help:HELP.delinquency},{label:'Saturação mediana',value:m.saturationMedian==null?'—':fmtPct.format(m.saturationMedian),sub:`${fmtN.format(m.highSat)} clientes acima de 90%`,help:HELP.saturation}];const riskToggle=`<div class="view-toggle"><button class="${state.creditRiskEntity==='customers'?'active':''}" data-risk-entity="customers">Clientes</button><button class="${state.creditRiskEntity==='guides'?'active':''}" data-risk-entity="guides">Guias</button></div>`;const summary=rows.slice(0,20);const summaryCols=[['name','Cliente','text'],['limitTotal','Limite total','money'],['open','Em aberto','money'],['available','Disponível','money'],['saturation','Saturação','saturation'],['risk','Risco total','money'],['delinquent','Inadimplência','money']];return`${pageHead('Visão Geral','Avalie exposição e disponibilidade de crédito com contexto suficiente para decidir onde aprofundar.')}${creditRuleNote()}${metricCards(cards)}<section class="grid2">${panel('Distribuição de saturação','Clique em uma faixa para filtrar a análise. Saturação = Valor em aberto ÷ Limite total.',`<div class="panel-body distribution">${dist.map(d=>`<button class="dist-card ${state.saturationClick===d.id?'active':''}" data-saturation-click="${d.id}"><strong>${fmtN.format(d.rows.length)}</strong><span>${d.label} · ${moneyShort(sum(d.rows,x=>x.risk))} de risco</span></button>`).join('')}</div>`)}${panel('Maiores riscos','Ranking por Risco total da entidade selecionada',barList(riskData.map(x=>({label:x.name,value:x.risk,display:moneyShort(x.risk),meta:state.creditRiskEntity==='customers'?`Saturação ${fmtPct.format(x.saturation||0)}`:`${x.customers} clientes`}))),riskToggle)}</section>${tablePanel('credit-overview','Clientes para consulta rápida','Lista de exceções; a página Clientes contém a análise completa.',summary,summaryCols,summaryCols,'customer')}`}
function creditCustomers(){const rows=creditCustomerRows(),m=creditMetrics();const cards=[{label:'Clientes analisados',value:fmtN.format(rows.length),sub:'com posição de crédito'},{label:'Limite total',value:moneyShort(m.limitTotal),sub:'carteira filtrada'},{label:'Limite disponível',value:moneyShort(m.available),sub:'com Recente',help:HELP.available},{label:'Risco total',value:moneyShort(m.risk),sub:'Aberto + Recente',help:HELP.risk},{label:'Inadimplência',value:moneyShort(m.delinq),sub:`${fmtN.format(m.delinqCount)} clientes`,cls:m.delinq>0?'down':''},{label:'Alta saturação / inadimplência',value:fmtN.format(new Set(rows.filter(x=>(x.saturation??0)>.9||x.delinquent>0).map(x=>x.id)).size),sub:'clientes para investigação'}];const summary=[['name','Cliente','text'],['guide','Guia atual','text'],['limitNormal','Limite normal','money'],['limitExtra','Limite extra','money'],['limitTotal','Limite total','money'],['open','Valor em aberto','money'],['available','Limite disponível','money'],['saturation','Saturação','saturation'],['risk','Risco total','money'],['delinquent','Inadimplência','money']];const detail=[...summary,['r3','Faturamento 3m','money'],['r6','Faturamento 6m','money'],['r12','Faturamento 12m','money'],['avgMonthly','Média mensal','money'],['limitToAvg','Limite / compra média','ratio'],['openToAvg','Em aberto / compra média','ratio'],['recent','Recente','money'],['band','Faixa','text'],['category','Categoria','text'],['status','Status comercial','status']];return`${pageHead('Clientes','Compare limite, exposição e comportamento de compra em uma mesma superfície analítica.')}${creditRuleNote()}${metricCards(cards)}${tablePanel('credit-customers','Clientes','Use a visão Detalhada para faturamento 3m/6m/12m e relações com compra média.',rows,summary,detail,'customer')}`}
function creditGuides(){const rows=creditGuideRows(),m=creditMetrics();const cards=[{label:'Nº de Guias',value:fmtN.format(rows.length),sub:'carteiras filtradas'},{label:'Limite total das carteiras',value:moneyShort(m.limitTotal),sub:'soma dos clientes'},{label:'Valor em aberto',value:moneyShort(m.open),sub:'carteira filtrada'},{label:'Risco total',value:moneyShort(m.risk),sub:'Aberto + Recente',help:HELP.risk},{label:'Inadimplência',value:moneyShort(m.delinq),sub:'valor total',cls:m.delinq>0?'down':''},{label:'Clientes inadimplentes',value:fmtN.format(m.delinqCount),sub:'na carteira filtrada'}];const cols=[['name','Guia','text'],['customers','Nº clientes','number'],['r3','Faturamento 3m','money'],['r6','Faturamento 6m','money'],['r12','Faturamento 12m','money'],['limitTotal','Limite total','money'],['open','Valor em aberto','money'],['risk','Risco total','money'],['delinquent','Inadimplência','money'],['saturation','Saturação referencial','saturation']];return`${pageHead('Guias','Avalie se o risco está concentrado em poucos clientes ou distribuído pela carteira de cada Guia.')}${creditRuleNote()}${metricCards(cards)}${tablePanel('credit-guides','Guias','Clique no Guia para abrir o contexto completo da carteira.',rows,cols,cols,'guide')}`}
function creditRuleNote(){return`<div class="note">Cenário demonstrativo baseado nas regras vigentes da V11: Limite total = Limite normal + Limite extra; Risco total = Valor em aberto + Recente; Saturação = Valor em aberto ÷ Limite total. ${info('Entenda as fórmulas',`${HELP.risk} ${HELP.saturation} ${HELP.available}`).replace('<span>Entenda as fórmulas</span>','<span style="font-weight:800">Entenda as fórmulas</span>')}</div>`}
function creditPage(){const tab=state.tabs.credit;if(tab==='overview')return creditOverview();if(tab==='customers')return creditCustomers();return creditGuides()}

function extraCustomerRows(){const moves=filteredMovements(),m=new Map();for(const x of moves){let r=m.get(x.customerId);if(!r)m.set(x.customerId,r={id:x.customerId,name:dims.customers.get(x.customerId)?.tradeName,count:0,increases:0,reductions:0,net:0,volume:0,last:null});r.count++;r.net+=x.movement;r.volume+=Math.abs(x.movement);if(x.movement>0)r.increases+=x.movement;if(x.movement<0)r.reductions+=Math.abs(x.movement);if(!r.last||r.last<x.date)r.last=x.date}for(const cid of customerSet())if(currentExtra(cid)>0&&!m.has(cid))m.set(cid,{id:cid,name:dims.customers.get(cid)?.tradeName,count:0,increases:0,reductions:0,net:0,volume:0,last:null});return[...m.values()].map(r=>{const cr=creditView(r.id),rev=revenueBetween(r.id,periodInfo().start,periodInfo().end);return{...r,final:currentExtra(r.id),limitNormal:cr?.limitNormal??null,limitTotal:cr?.limitTotal??null,available:cr?.available??null,open:cr?.valueOpen??null,risk:cr?.riskTotal??null,delinquent:cr?.delinquent??null,revenue:rev,band:currentBand(r.id),category:currentCategory.get(r.id)?.categoryId,guide:dims.guides.get(customerGuide(r.id))?.tradeName}}).sort((a,b)=>b.final-a.final||b.volume-a.volume)}
function extraGuideRows(){const clients=extraCustomerRows(),m=new Map();for(const c of clients){const gid=customerGuide(c.id);let r=m.get(gid);if(!r)m.set(gid,r={id:gid,name:dims.guides.get(gid)?.tradeName,customers:0,revenue:0,extraCurrent:0,net:0,movements:0,risk:0,delinquent:0});r.customers++;r.revenue+=c.revenue;r.extraCurrent+=c.final;r.net+=c.net;r.movements+=c.count;r.risk+=c.risk||0;r.delinquent+=c.delinquent||0}return[...m.values()].sort((a,b)=>b.extraCurrent-a.extraCurrent)}
function extraEffectRows(){const p=periodInfo(),events=filteredMovements().filter(x=>x.movement>0),rows=[];for(const e of events){const eventMonth=monthKey(e.date),beforeMonths=[addMonths(eventMonth,-2),addMonths(eventMonth,-1)],afterMonths=[addMonths(eventMonth,1),addMonths(eventMonth,2)],beforeStart=firstDay(beforeMonths[0]),beforeEnd=lastDay(beforeMonths[1]),afterStart=firstDay(afterMonths[0]),afterEnd=lastDay(afterMonths[1]),completeAfter=afterEnd<=DATA_AS_OF,before=revenueBetween(e.customerId,beforeStart,beforeEnd),after=completeAfter?revenueBetween(e.customerId,afterStart,afterEnd):revenueBetween(e.customerId,afterStart,DATA_AS_OF),other=(limitByCustomer.get(e.customerId)||[]).filter(x=>x.reviewId!==e.reviewId&&x.date>=beforeStart&&x.date<=afterEnd),cr=creditView(e.customerId);rows.push({id:e.reviewId,reviewId:e.reviewId,customerId:e.customerId,name:dims.customers.get(e.customerId)?.tradeName,guide:dims.guides.get(e.guideId)?.tradeName,date:e.date,previous:e.previousLimit,newLimit:e.newLimit,increase:e.movement,beforeMonths:beforeMonths.map(monthName).join(' + '),afterMonths:afterMonths.map(monthName).join(' + '),before,beforeAvg:before/2,after,afterAvg:completeAfter?after/2:null,deltaAbs:completeAfter?after-before:null,delta:completeAfter&&before?(after-before)/before:null,completeAfter,otherMovements:other.length,limitNormal:cr?.limitNormal??null,limitTotal:cr?.limitTotal??null,saturation:cr?.saturation??null,open:cr?.valueOpen??null,risk:cr?.riskTotal??null,delinquent:cr?.delinquent??null})}return rows.sort((a,b)=>Math.abs(b.deltaAbs||0)-Math.abs(a.deltaAbs||0))}
function extraOverview(){const m=extraMetrics(),clients=extraCustomerRows(),effects=extraEffectRows(),risk=sum(clients,x=>x.risk||0),delinq=sum(clients,x=>x.delinquent||0);const cards=[{label:'Limite Extra atual',value:moneyShort(sum([...customerSet()],currentExtra)),sub:'saldo atual dos clientes filtrados'},{label:'Variação líquida',value:`${m.net>=0?'+':''}${moneyShort(m.net)}`,sub:`Aumentos ${moneyShort(m.increases)} · reduções ${moneyShort(m.reductions)}`,cls:m.net>=0?'up':'down'},{label:'Clientes com Limite Extra',value:fmtN.format([...customerSet()].filter(c=>currentExtra(c)>0).length),sub:'posição atual'},{label:'Movimentações no período',value:fmtN.format(m.count),sub:`${m.increaseCount} aumentos · ${m.reductionCount} reduções`},{label:'Valor total aumentado',value:moneyShort(m.increases),sub:'aumentos brutos no período'},{label:'Risco atual',value:moneyShort(risk),sub:`Inadimplência ${moneyShort(delinq)}`,help:HELP.risk}];const effectSummary=effects.slice(0,12),effectCols=[['name','Cliente','text'],['date','Data aumento','date'],['increase','Aumento','moneySigned'],['before','Fat. total antes','money'],['beforeAvg','Média mensal antes','money'],['after','Fat. total depois','money'],['afterAvg','Média mensal depois','money'],['deltaAbs','Variação R$','moneySigned'],['delta','Variação %','pct']];const compact=clients.slice(0,8).map(x=>({label:x.name,value:x.final,display:moneyShort(x.final),meta:`Δ no período ${x.net>=0?'+':''}${moneyShort(x.net)} · risco ${moneyShort(x.risk||0)}`}));return`${pageHead('Visão Geral','Entenda quanto foi concedido, como o Limite Extra se movimentou e o que aconteceu com o faturamento após os aumentos.')}${metricCards(cards)}<section class="grid2">${panel('Efeito após aumento',`Metodologia: ${HELP.effect}`,barList(effects.slice(0,8).map(x=>({label:x.name,value:Math.abs(x.deltaAbs||0),display:x.delta==null?'sem base':`${x.delta>=0?'+':''}${fmtPct.format(x.delta)}`,meta:`${x.beforeMonths} → ${x.afterMonths}${x.completeAfter?'':' · janela pós-aumento incompleta'}${x.otherMovements?' · outras movimentações na janela':''}`}))))}${panel('Maiores saldos atuais','Resumo compacto — a página Clientes contém a tabela completa',barList(compact))}</section>${tablePanel('extra-effects','Eventos de aumento','Clique no Cliente/evento para abrir a história da concessão. A variação indica associação temporal, não causalidade.',effectSummary,effectCols,effectCols,'extraEffect')}`}
function extraMovements(){const moves=filteredMovements(),m=extraMetrics(),rows=moves.map(x=>({id:x.customerId,reviewId:x.reviewId,customerId:x.customerId,name:dims.customers.get(x.customerId)?.tradeName,guide:dims.guides.get(x.guideId)?.tradeName,date:x.date,type:x.type,previous:x.previousLimit,movement:x.movement,newLimit:x.newLimit,history:x.previousHistoryKnown?'Histórico anterior conhecido':'Primeiro registro disponível'}));const cards=[{label:'Nº de movimentações',value:fmtN.format(m.count),sub:'no período'},{label:'Aumentos',value:moneyShort(m.increases),sub:`${m.increaseCount} movimentos`},{label:'Reduções',value:moneyShort(m.reductions),sub:`${m.reductionCount} movimentos`},{label:'Variação líquida',value:`${m.net>=0?'+':''}${moneyShort(m.net)}`,sub:'aumentos − reduções',cls:m.net>=0?'up':'down'},{label:'Clientes movimentados',value:fmtN.format(m.customers),sub:'clientes distintos'},{label:'Valor médio por movimentação',value:moneyShort(m.count?m.volume/m.count:0),sub:'volume absoluto ÷ movimentos'}];const cols=[['name','Cliente','text'],['guide','Guia da movimentação','text'],['date','Data','date'],['type','Tipo','text'],['previous','Valor anterior','money'],['movement','Movimentação','moneySigned'],['newLimit','Valor após movimento','money'],['history','Histórico','text']];return`${pageHead('Movimentações','Consulte cada evento de Limite Extra sem perder o contexto do período e dos filtros.')}${metricCards(cards)}${tablePanel('extra-movements','Movimentações','A tabela preserva o sinal original da movimentação e identifica registros sem histórico anterior comprovado.',rows,cols,cols,'customer')}`}
function extraCustomers(){const rows=extraCustomerRows(),m=extraMetrics(),cards=[{label:'Clientes com Limite Extra',value:fmtN.format([...customerSet()].filter(c=>currentExtra(c)>0).length),sub:'posição atual'},{label:'Limite Extra atual',value:moneyShort(sum([...customerSet()],currentExtra)),sub:'saldo atual'},{label:'Variação no período',value:`${m.net>=0?'+':''}${moneyShort(m.net)}`,sub:'movimentação líquida',cls:m.net>=0?'up':'down'},{label:'Clientes com aumento',value:fmtN.format(new Set(m.moves.filter(x=>x.movement>0).map(x=>x.customerId)).size),sub:'no período'},{label:'Clientes com redução',value:fmtN.format(new Set(m.moves.filter(x=>x.movement<0).map(x=>x.customerId)).size),sub:'no período'},{label:'Risco / Inadimplência',value:moneyShort(sum(rows,x=>x.risk||0)),sub:`Inadimplência ${moneyShort(sum(rows,x=>x.delinquent||0))}`}];const summary=[['name','Cliente','text'],['count','Movimentos','number'],['increases','Aumentos','money'],['reductions','Reduções','money'],['net','Variação','moneySigned'],['final','Limite Extra atual','money'],['last','Última movimentação','date']];const detail=[...summary,['revenue','Faturamento','money'],['limitNormal','Limite normal','money'],['limitTotal','Limite total','money'],['available','Disponível','money'],['open','Em aberto','money'],['risk','Risco','money'],['delinquent','Inadimplência','money'],['band','Faixa','text'],['category','Categoria','text'],['guide','Guia atual','text']];return`${pageHead('Clientes','Compare saldos e movimentações; use o Drawer para ver todo o histórico individual.')}${metricCards(cards)}${tablePanel('extra-customers','Clientes com Limite Extra','A visão Detalhada cruza Limite Extra com Crédito, faturamento e contexto comercial.',rows,summary,detail,'customer')}`}
function extraGuides(){const rows=extraGuideRows(),m=extraMetrics(),cards=[{label:'Nº de Guias',value:fmtN.format(rows.length),sub:'com clientes no contexto'},{label:'Clientes com Limite Extra',value:fmtN.format([...customerSet()].filter(c=>currentExtra(c)>0).length),sub:'posição atual'},{label:'Limite Extra das carteiras',value:moneyShort(sum(rows,x=>x.extraCurrent)),sub:'posição atual'},{label:'Variação líquida',value:`${m.net>=0?'+':''}${moneyShort(m.net)}`,sub:'movimentos no período',cls:m.net>=0?'up':'down'},{label:'Risco atual',value:moneyShort(sum(rows,x=>x.risk)),sub:'carteiras filtradas'},{label:'Inadimplência',value:moneyShort(sum(rows,x=>x.delinquent)),sub:'carteiras filtradas'}];const cols=[['name','Guia','text'],['customers','Nº clientes','number'],['revenue','Faturamento da carteira','money'],['extraCurrent','Limite Extra atual','money'],['net','Variação no período','moneySigned'],['movements','Nº movimentações','number'],['risk','Risco atual','money'],['delinquent','Inadimplência','money']];return`${pageHead('Guias','Entenda quais carteiras concentram Limite Extra e quais clientes geraram a variação do período.')}${metricCards(cards)}${tablePanel('extra-guides','Guias','Clique no Guia para abrir clientes, risco e origem da variação.',rows,cols,cols,'guide')}`}
function extraPage(){const tab=state.tabs.extra;if(tab==='overview')return extraOverview();if(tab==='movements')return extraMovements();if(tab==='customers')return extraCustomers();return extraGuides()}

function bandRows(){const p=periodInfo(),ids=[...customerSet()],revMap=new Map();for(const b of filteredBillings())revMap.set(b.customerId,(revMap.get(b.customerId)||0)+b.value);return ids.map(cid=>{const arr=bandByCustomer.get(cid)||[],first=arr.find(x=>x.month===state.filters.fromMonth),last=arr.find(x=>x.month===state.filters.toMonth),initial=first?.band||'SEM FATURAMENTO',final=last?.band||'SEM FATURAMENTO',migration=bandOrder(final)-bandOrder(initial),cr=creditView(cid),bh=behavior.get(cid),periodRevenue=revMap.get(cid)||0;return{id:cid,name:dims.customers.get(cid)?.tradeName,firstBand:initial,finalBand:final,migration,revenue:periodRevenue,category:currentCategory.get(cid)?.categoryId,status:bh?.status,delinquent:cr?.delinquent??null,guide:dims.guides.get(customerGuide(cid))?.tradeName,limitTotal:cr?.limitTotal??null,limitExtra:cr?.limitExtra??null,risk:cr?.riskTotal??null,avgMonthly:p.months.length?periodRevenue/p.months.length:null,firstRef:first?.month||state.filters.fromMonth,lastRef:last?.month||state.filters.toMonth}})}
function migrationMatrix(rows,metric){const bands=DATA.parameters.revenueBands;const cells=new Map();for(const r of rows){const key=`${r.firstBand}|${r.finalBand}`,v=metric==='revenue'?r.revenue:1;cells.set(key,(cells.get(key)||0)+v)}return`<div class="matrix-wrap"><div class="matrix"><div class="head">Inicial ↓ / Final →</div>${bands.map(b=>`<div class="head">${esc(b)}</div>`).join('')}${bands.map(a=>`<div class="head">${esc(a)}</div>${bands.map(b=>{const v=cells.get(`${a}|${b}`)||0,move=bandOrder(b)-bandOrder(a);return`<div class="cell ${move>0?'cool':move<0?'hot':''}">${metric==='revenue'?moneyShort(v):fmtN.format(v)}</div>`}).join('')}`).join('')}</div></div>`}
function bandsOverview(){const rows=bandRows(),up=rows.filter(x=>x.migration>0),down=rows.filter(x=>x.migration<0),same=rows.filter(x=>x.migration===0),rev=sum(rows,x=>x.revenue),cards=[{label:'Clientes analisados',value:fmtN.format(rows.length),sub:`${monthName(state.filters.fromMonth)} → ${monthName(state.filters.toMonth)}`},{label:'Subiram de faixa',value:fmtN.format(up.length),sub:'↑ evolução entre início e fim',cls:'up'},{label:'Caíram de faixa',value:fmtN.format(down.length),sub:'↓ regressão entre início e fim',cls:'down'},{label:'Mantiveram faixa',value:fmtN.format(same.length),sub:'→ mesma faixa'},{label:'Faturamento total',value:moneyShort(rev),sub:'clientes analisados'},{label:'Faturamento de quem subiu',value:moneyShort(sum(up,x=>x.revenue)),sub:rev?fmtPct.format(sum(up,x=>x.revenue)/rev):'—'}];const firstDist=DATA.parameters.revenueBands.map(b=>({label:b,value:rows.filter(x=>x.firstBand===b).length,display:fmtN.format(rows.filter(x=>x.firstBand===b).length),meta:'clientes'})),finalDist=DATA.parameters.revenueBands.map(b=>({label:b,value:rows.filter(x=>x.finalBand===b).length,display:fmtN.format(rows.filter(x=>x.finalBand===b).length),meta:'clientes'}));return`${pageHead('Visão Geral','Entenda distribuição e migração entre a primeira e a última referência do período, sem repetir a tabela completa de Clientes.')}${metricCards(cards)}<div class="note info-note">${HELP.bands} Período analisado: ${monthName(state.filters.fromMonth)} a ${monthName(state.filters.toMonth)}. Faixa inicial = ${monthName(state.filters.fromMonth)}; Faixa final = ${monthName(state.filters.toMonth)}.</div><section class="grid2">${panel('Distribuição por faixa inicial',monthName(state.filters.fromMonth),barList(firstDist))}${panel('Distribuição por faixa final',monthName(state.filters.toMonth),barList(finalDist))}</section>${panel('Matriz de migração','Linhas = faixa inicial; colunas = faixa final. Verde indica subida e vermelho indica queda.',migrationMatrix(rows,'customers'))}<section class="gainloss"><article><span>Faturamento · subiram</span><strong class="up">${moneyShort(sum(up,x=>x.revenue))}</strong></article><article><span>Faturamento · mantiveram</span><strong>${moneyShort(sum(same,x=>x.revenue))}</strong></article><article><span>Faturamento · caíram</span><strong class="down">${moneyShort(sum(down,x=>x.revenue))}</strong></article></section>`}
function bandsCustomers(){const rows=bandRows(),up=rows.filter(x=>x.migration>0).length,down=rows.filter(x=>x.migration<0).length,same=rows.filter(x=>x.migration===0).length,cards=[{label:'Clientes analisados',value:fmtN.format(rows.length),sub:'no recorte'},{label:'Subiram',value:fmtN.format(up),sub:'↑ faixa final superior',cls:'up'},{label:'Caíram',value:fmtN.format(down),sub:'↓ faixa final inferior',cls:'down'},{label:'Mantiveram',value:fmtN.format(same),sub:'→ mesma faixa'},{label:'Faturamento total',value:moneyShort(sum(rows,x=>x.revenue)),sub:'período filtrado'},{label:'Inadimplência',value:moneyShort(sum(rows,x=>x.delinquent||0)),sub:'contexto de Crédito'}];const metricToggle=`<div class="view-toggle"><button class="${state.bandsMetric==='customers'?'active':''}" data-bands-metric="customers">Nº clientes</button><button class="${state.bandsMetric==='revenue'?'active':''}" data-bands-metric="revenue">Faturamento</button></div>`;const summary=[['name','Cliente','text'],['firstBand','Faixa inicial','text'],['finalBand','Faixa final','text'],['migration','Movimento','migration'],['revenue','Faturamento no período','money'],['category','Categoria','text'],['status','Status comercial','status'],['delinquent','Inadimplência','money']];const detail=[...summary,['guide','Guia atual','text'],['limitTotal','Limite total','money'],['limitExtra','Limite extra','money'],['risk','Risco total','money'],['avgMonthly','Média mensal','money'],['firstRef','Primeira referência','text'],['lastRef','Última referência','text']];return`${pageHead('Clientes','A antiga Evolução foi incorporada a esta página: gráfico, migração e tabela única agora formam uma análise contínua.')}${metricCards(cards)}${panel('Evolução das faixas','Quantidade de clientes ou faturamento por faixa ao longo do período.',multiBandChart(state.bandsMetric),metricToggle)}${panel('Migração entre faixas',`Métrica atual: ${state.bandsMetric==='customers'?'Nº de clientes':'Faturamento'}.`,migrationMatrix(rows,state.bandsMetric))}${tablePanel('bands-customers','Clientes e trajetória','A tabela compara clientes; o Drawer conta a história individual mês a mês.',rows,summary,detail,'customer')}`}
function bandsPage(){return state.tabs.bands==='overview'?bandsOverview():bandsCustomers()}

function signalFor(cid){const p=periodInfo(),cur=revenueBetween(cid,p.start,p.end),prev=p.comparison?revenueBetween(cid,p.comparison.start,p.comparison.end):0,v=variation(cur,prev),cr=creditView(cid),cat=currentCategory.get(cid)?.categoryId||'—',sat=cr?.saturation||0,moves=(limitByCustomer.get(cid)||[]).filter(x=>x.date>=p.start&&x.date<=p.end),extraNet=sum(moves,x=>x.movement);if(cr?.available<0||cr?.delinquent>0)return{label:'Crédito pressionado',cls:'bad',reason:cr.available<0?'Disponível negativo':'Inadimplência presente'};if(['A','B'].includes(cat)&&v!=null&&v>.15&&sat>.7)return{label:'Potencial de revisão',cls:'attn',reason:'Crescimento + utilização elevada'};if(extraNet>15000&&v!=null&&v<-.05)return{label:'Limite Extra sem tração',cls:'attn',reason:'Aumento de limite com queda de faturamento'};if(v!=null&&v>.18&&sat<.55)return{label:'Crescimento saudável',cls:'good',reason:'Crescimento com folga de crédito'};return{label:'Monitorar',cls:'neutral',reason:'Sem sinal crítico no cenário fictício'}}
function integratedRows(){const p=periodInfo();return[...customerSet()].map(cid=>{const c=dims.customers.get(cid),rev=revenueBetween(cid,p.start,p.end),prev=p.comparison?revenueBetween(cid,p.comparison.start,p.comparison.end):0,cr=creditView(cid),sig=signalFor(cid),moves=(limitByCustomer.get(cid)||[]).filter(x=>x.date>=p.start&&x.date<=p.end);return{id:cid,name:c.tradeName,guide:dims.guides.get(c.currentGuideId)?.tradeName,rp:dims.rps.get(customerRp(cid))?.name,category:currentCategory.get(cid)?.categoryId,revenue:rev,delta:variation(rev,prev),band:currentBand(cid),limitTotal:cr?.limitTotal||0,risk:cr?.riskTotal||0,available:cr?.available||0,saturation:cr?.saturation||0,delinquent:cr?.delinquent||0,extraNet:sum(moves,x=>x.movement),signal:sig.label,signalCls:sig.cls,reason:sig.reason}})}
function executivePage(){const rows=integratedRows(),r=revenueMetrics(),c=creditMetrics(),e=extraMetrics();if(state.tabs.executive==='signals'){const cols=[['name','Cliente','text'],['category','Categoria','text'],['revenue','Faturamento','money'],['delta','Variação','pct'],['band','Faixa','text'],['available','Disponível','money'],['saturation','Saturação','saturation'],['extraNet','Variação Limite Extra','moneySigned'],['signal','Sinal','text']];return`${pageHead('Sinais integrados','Módulo preservado da V11 nesta rodada. Os sinais apoiam investigação e não constituem decisão automática de crédito.')}<div class="note">Visão Executiva está fora do escopo de reformulação da V12 e será tratada em Fase 2.</div>${tablePanel('executive-signals','Sinais por Cliente','Cruzamento demonstrativo de Faturamento, Crédito, Categoria e Limite Extra.',rows.sort((a,b)=>b.risk-a.risk),cols,cols,'customer')}`}
const cards=[{label:'Faturamento',value:moneyShort(r.rev),sub:`${fmtN.format(r.customers)} clientes`},{label:'Variação',value:r.var==null?'—':`${r.var>=0?'+':''}${fmtPct.format(r.var)}`,sub:comparisonText(),cls:r.var>=0?'up':'down'},{label:'Limite total',value:moneyShort(c.limitTotal),sub:'posição de crédito'},{label:'Risco total',value:moneyShort(c.risk),sub:'Aberto + Recente'},{label:'Disponível',value:moneyShort(c.available),sub:`${rows.filter(x=>x.available<0).length} negativos`,cls:c.available<0?'down':''},{label:'Limite Extra líquido',value:`${e.net>=0?'+':''}${moneyShort(e.net)}`,sub:`${e.count} movimentos`,cls:e.net>=0?'up':'down'}];const top=[...rows].sort((a,b)=>b.risk-a.risk).slice(0,10);return`${pageHead('Visão Executiva','Versão preservada da V11; a reformulação dedicada está explicitamente postergada para Fase 2.')}<div class="note">Visão Executiva permanece acessível e funcional, sem redesign estrutural nesta V12.</div>${metricCards(cards)}<section class="grid2">${panel('Faturamento',comparisonText(),lineChart(revenueByMonth(r.cur,periodInfo().months),periodInfo().comparison?revenueByMonth(r.prev,periodInfo().comparison.months):null))}${panel('Maiores riscos','Consulta integrada preservada',barList(top.map(x=>({label:x.name,value:x.risk,display:moneyShort(x.risk),meta:x.signal}))))}</section>`}
function customerPage(){let cid=state.customer360Id;if(!cid||!customerSet().has(cid)){cid=[...customerSet()][0]||DATA.dimensions.customers[0].id;state.customer360Id=cid}const c=dims.customers.get(cid),cr=creditView(cid),bh=behavior.get(cid),p=periodInfo(),rev=revenueBetween(cid,p.start,p.end),prev=p.comparison?revenueBetween(cid,p.comparison.start,p.comparison.end):0,moves=(limitByCustomer.get(cid)||[]).filter(x=>x.date>=p.start&&x.date<=p.end),series=revenueByMonth((billByCustomer.get(cid)||[]).filter(x=>x.date>=p.start&&x.date<=p.end),p.months),options=[...customerSet()].map(id=>`<option value="${id}" ${id===cid?'selected':''}>${esc(dims.customers.get(id)?.tradeName)}</option>`).join(''),head=`<section class="customer-head"><div><span class="eyebrow">Cliente 360 · Fase 2</span><h1>${esc(c?.tradeName)}</h1><p>${esc(c?.city)}/${c?.uf} · ${esc(dims.guides.get(c?.currentGuideId)?.tradeName)} · Categoria ${currentCategory.get(cid)?.categoryId||'—'}</p></div><select class="customer-select" data-customer360>${options}</select></section><div class="note">Cliente 360 permanece funcional como na V11. Sua reformulação completa está postergada para Fase 2.</div>`;const tab=state.tabs.customer;if(tab==='summary')return`${head}<section class="facts"><div class="fact"><span>Faturamento</span><strong>${fmtBRL.format(rev)}</strong></div><div class="fact"><span>Variação</span><strong>${variation(rev,prev)==null?'—':fmtPct.format(variation(rev,prev))}</strong></div><div class="fact"><span>Faixa atual</span><strong>${esc(currentBand(cid))}</strong></div><div class="fact"><span>Status comercial</span><strong>${statusBadge(bh?.status)}</strong></div><div class="fact"><span>Limite total</span><strong>${fmtBRL.format(cr?.limitTotal||0)}</strong></div><div class="fact"><span>Risco total</span><strong>${fmtBRL.format(cr?.riskTotal||0)}</strong></div><div class="fact"><span>Disponível</span><strong>${fmtBRL.format(cr?.available||0)}</strong></div><div class="fact"><span>Saturação</span><strong>${cr?.saturation==null?'—':fmtPct.format(cr.saturation)}</strong></div></section><section class="grid2">${panel('Faturamento','Evolução no recorte',lineChart(series,null,['Faturamento']))}${panel('Sinal integrado','Leitura preservada da V11',`<div class="panel-body"><span class="signal ${signalFor(cid).cls}">${signalFor(cid).label}</span><p>${esc(signalFor(cid).reason)}</p></div>`)}</section>`;if(tab==='revenue'){const rows=(billByCustomer.get(cid)||[]).filter(x=>x.date>=p.start&&x.date<=p.end).map(x=>({date:x.date,store:dims.stores.get(x.storeId)?.tradeName,guide:dims.guides.get(x.saleGuideId)?.tradeName,value:x.value}));return`${head}${panel('Evolução do faturamento','Histórico no período selecionado',lineChart(series))}${tablePanel('customer360-revenue','Faturamentos','Histórico individual preservado.',rows,[['date','Data','date'],['store','Loja','text'],['guide','Guia da venda','text'],['value','Valor','money']])}`};if(tab==='credit')return`${head}${creditRuleNote()}${metricCards([{label:'Limite normal',value:fmtBRL.format(cr?.limitNormal||0)},{label:'Limite Extra',value:fmtBRL.format(cr?.limitExtra||0)},{label:'Valor em aberto',value:fmtBRL.format(cr?.valueOpen||0)},{label:'Recente',value:fmtBRL.format(cr?.valueRecent||0)},{label:'Risco total',value:fmtBRL.format(cr?.riskTotal||0)},{label:'Disponível',value:fmtBRL.format(cr?.available||0)}])}`;return`${head}${metricCards([{label:'Saldo atual',value:fmtBRL.format(currentExtra(cid))},{label:'Aumentos',value:fmtBRL.format(sum(moves.filter(x=>x.movement>0),x=>x.movement))},{label:'Reduções',value:fmtBRL.format(sum(moves.filter(x=>x.movement<0),x=>Math.abs(x.movement)))},{label:'Líquido',value:fmtBRL.format(sum(moves,x=>x.movement))},{label:'Movimentos',value:fmtN.format(moves.length)}])}`}

function drawerSection(title,body,extra=''){return`<section class="drawer-section"><header><h3>${title}</h3>${extra}</header><div class="body">${body}</div></section>`}
function factsHtml(items){return`<div class="facts">${items.map(([l,v])=>`<div class="fact"><span>${l}</span><strong>${v==null?'—':v}</strong></div>`).join('')}</div>`}
function miniTable(rows,cols){return`<div style="overflow:auto"><table class="mini-table"><thead><tr>${cols.map(c=>`<th class="${c[2]==='money'?'num':''}">${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>{const v=r[c[0]];return`<td class="${c[2]==='money'?'num':''}">${c[2]==='money'?(v==null?'—':fmtBRL.format(v)):c[2]==='pct'?(v==null?'—':fmtPct.format(v)):esc(v??'—')}</td>`}).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}">Sem dados.</td></tr>`}</tbody></table></div>`}
function entityRevenueSeries(kind,id){const p=periodInfo(),pred=kind==='customer'?x=>x.customerId===id:kind==='guide'?x=>x.saleGuideId===id:kind==='store'?x=>x.storeId===id:x=>dims.stores.get(x.storeId)?.segmentId===id;const rows=filteredBillings().filter(pred),prev=filteredBillings(true).filter(pred);return{cur:revenueByMonth(rows,p.months),prev:p.comparison?revenueByMonth(prev,p.comparison.months):null}}
function revenueGuideDrawer(gid){const g=dims.guides.get(gid),rows=filteredBillings().filter(x=>x.saleGuideId===gid),agg=revenueGuideRows().find(x=>x.id===gid),portfolio=DATA.dimensions.customers.filter(c=>c.currentGuideId===gid&&customerSet().has(c.id)),credit=portfolio.map(c=>creditView(c.id)).filter(Boolean),top=revenueCustomerRows().filter(c=>portfolio.some(p=>p.id===c.id)).sort((a,b)=>b.revenue-a.revenue).slice(0,10),series=entityRevenueSeries('guide',gid),rev=sum(rows,x=>x.value),months=periodInfo().months.length;return`${drawerSection('Resumo',factsHtml([['Faturamento',fmtBRL.format(rev)],['Média mensal',fmtBRL.format(months?rev/months:0)],['Nº clientes',fmtN.format(distinct(rows,x=>x.customerId))],['Nº lojas',fmtN.format(distinct(rows,x=>x.storeId))],['Nº faturamentos',fmtN.format(distinct(rows,x=>x.id))],['Curva ABC',abcBadge(agg?.curve)]]))}${drawerSection('Faturamento histórico',lineChart(series.cur,series.prev,['Atual','Comparação'],true))}${drawerSection('Crédito da carteira atual',factsHtml([['Limite total',fmtBRL.format(sum(credit,x=>x.limitTotal))],['Limite normal',fmtBRL.format(sum(credit,x=>x.limitNormal))],['Limite Extra',fmtBRL.format(sum(credit,x=>x.limitExtra))],['Limite consumido',fmtBRL.format(sum(credit,x=>x.consumed))],['Disponível',fmtBRL.format(sum(credit,x=>x.available))],['Valor em aberto',fmtBRL.format(sum(credit,x=>x.valueOpen))],['Risco total',fmtBRL.format(sum(credit,x=>x.riskTotal))],['Inadimplência',fmtBRL.format(sum(credit,x=>x.delinquent))],['Clientes inadimplentes',fmtN.format(credit.filter(x=>x.delinquent>0).length)]]))}${drawerSection('Top 10 clientes da carteira',miniTable(top.map(x=>({name:x.name,revenue:x.revenue,share:x.share,curve:x.curve,status:x.status,limit:creditView(x.id)?.limitTotal,risk:creditView(x.id)?.riskTotal,delinq:creditView(x.id)?.delinquent})),[['name','Cliente','text'],['revenue','Faturamento','money'],['limit','Limite total','money'],['risk','Risco','money'],['delinq','Inadimplência','money']]))}`}
